// Mobile BFF: aggregates multiple downstream calls into one response
app.get('/home-screen', async (req, res) => {
  const [user, feed, notifications] = await Promise.all([
    userService.getProfile(req.userId),
    feedService.getTopPosts(req.userId, { limit: 10 }),
    notificationService.getUnread(req.userId),
  ]);
  res.json({
    user: { name: user.name, avatar: user.avatarUrl },
    posts: feed.map(p => ({ id: p.id, title: p.title })),
    unreadCount: notifications.length,
  });
});

