// order.proto — shared contract between services
syntax = "proto3";

package order;

service OrderService {
  rpc GetOrder (GetOrderRequest) returns (Order);
  rpc StreamOrderUpdates (GetOrderRequest) returns (stream Order);
}

message GetOrderRequest {
  string order_id = 1;
}

message Order {
  string order_id = 1;
  string status   = 2;
  double total    = 3;
}

# Client query — only fetches fields it needs
query GetOrderSummary($orderId: ID!) {
  order(id: $orderId) {
    id
    status
    customer {
      name
    }
    items {
      productName
      quantity
      price
    }
  }
}
# Server returns exactly this shape — no unused fields

// product.proto
syntax = "proto3";

package catalog;

message Product {
  string id          = 1;
  string name        = 2;
  double price       = 3;
  int32  stock_count = 4;
  // Field 5 added later — old consumers safely ignore it
  string category    = 5;
}
// Wire encoding: only field numbers + values, no field names

// Kafka Pub/Sub: publisher
await producer.send({
  topic: 'order.placed',
  messages: [{ value: JSON.stringify({ orderId, userId, total }) }],
});

// Kafka Pub/Sub: independent subscriber (notification service)
consumer.subscribe({ topic: 'order.placed', fromBeginning: false });
for await (const { value } of consumer.run()) {
  const event = JSON.parse(value.toString());
  await sendConfirmationEmail(event.userId, event.orderId);
}

