    func reserve(productId: String, qty: Int) async throws
}

// Step 2: Old implementation (HTTP) — existing code, now conforming
struct HttpInventoryAdapter: InventoryPort {
    func reserve(productId: String, qty: Int) async throws {
        // existing HTTP call
    }
}

// New implementation (Kafka event)
struct KafkaInventoryAdapter: InventoryPort {
    func reserve(productId: String, qty: Int) async throws {
        // publish ReserveInventory event to Kafka
    }
}

// Step 3: Feature flag selects implementation
let adapter: InventoryPort = featureFlag.isEnabled("kafka-inventory")
    ? KafkaInventoryAdapter()
    : HttpInventoryAdapter()

// Timeout + fallback prevents cascade
func fetchRecommendations(userId: String) async -> [Product] {
    do {
        return try await withTimeout(seconds: 0.5) {
            try await recommendationService.get(userId)
        }
    } catch {
        // Circuit open or timeout — return cached defaults
        return await cache.getTopProducts()
    }
}

